<?php
require 'includes/db.php';require 'includes/functions.php';$id=(int)($_GET['id']??0);$s=$conn->prepare('SELECT b.*,AVG(r.rating) avg_rating,COUNT(r.id) reviews FROM books b LEFT JOIN reviews r ON r.book_id=b.id WHERE b.id=? GROUP BY b.id');$s->bind_param('i',$id);$s->execute();$b=$s->get_result()->fetch_assoc();if(!$b)exit('Book not found');
$r=$conn->prepare('SELECT r.rating,r.comment,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.book_id=? ORDER BY r.created_at DESC');$r->bind_param('i',$id);$r->execute();$rs=$r->get_result();$page_title=$b['title'];include 'includes/header.php';?>
<div class="detail"><div class="cover">📘</div><section><p class="muted"><?=e($b['category'])?></p><h1><?=e($b['title'])?></h1><p>By <?=e($b['author'])?></p><p><?=e($b['description'])?></p><p class="price"><?=cash($b['price'])?></p><p>Available stock: <?=$b['stock']?></p><p class="stars">★ <?=number_format((float)$b['avg_rating'],1)?> / 5 (<?=$b['reviews']?> reviews)</p><form method="post" action="cart/add.php"><input type="hidden" name="book_id" value="<?=$id?>"><label>Quantity</label><input type="number" name="quantity" min="1" max="<?=max(1,$b['stock'])?>" value="1"><button class="btn" <?=$b['stock']<1?'disabled':''?>>Add to Cart</button></form><form method="post" action="wishlist.php"><input type="hidden" name="book_id" value="<?=$id?>"><button class="btn">Add to Wishlist</button></form></section></div><h2>Reviews</h2>
<?php if(logged()):?><form class="panel" method="post" action="review.php"><input type="hidden" name="book_id" value="<?=$id?>"><label>Rating</label><select name="rating"><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>"><?=$i?> star(s)</option><?php endfor;?></select><textarea name="comment" placeholder="Write a review"></textarea><button class="btn">Submit Review</button></form><?php else:?><p><a href="auth/login.php">Login</a> to review.</p><?php endif;?>
<?php while($x=$rs->fetch_assoc()):?><div class="panel"><b><?=e($x['name'])?></b> <span class="stars"><?=str_repeat('★',(int)$x['rating'])?></span><p><?=e($x['comment'])?></p></div><?php endwhile;?><?php include 'includes/footer.php';?>
